from __future__ import annotations

import asyncio
import logging
import time
from time import sleep
from typing import TYPE_CHECKING, cast

import requests
from pysnmp.hlapi.asyncio import (
    ObjectIdentity,
    ObjectType,
    setCmd,
)
from pysnmp.proto import rfc1902
from pysnmp.proto.secmod.rfc3414.auth import hmacmd5, hmacsha
from pysnmp.proto.secmod.rfc3414.priv import des
from pysnmp.proto.secmod.rfc3826.priv import aes


from taf.hw.pdu.exceptions import BadDeviceStatus, BadResponse, PduConnectionError

from .base import PDU, DeviceStatus
from .snmp import SnmpPdu

if TYPE_CHECKING:
    from requests.models import Response


class FPFH:
    """Factory class for FPFH PDU implementations"""

    def __new__(cls, host, timeout=20, **kwargs):
        login = kwargs.pop("login", "admin")
        password = kwargs.pop("password", None) or "admin"
        protocol = kwargs.pop("protocol", None) or "http"
        snmp_user = kwargs.pop("snmp_user", None)
        http_proxy = kwargs.pop("http_proxy", None)
        if protocol == "snmp":
            return FPFHsnmp(host=host, timeout=timeout, snmp_user=snmp_user)
        elif protocol == "http":
            return FPFHhttp(
                host=host,
                timeout=timeout,
                login=login,
                password=password,
                http_proxy=http_proxy,
            )
        else:
            raise ValueError(f"Non-supported protocol: {protocol}")


FPFH = cast(PDU, FPFH)


class FPFHhttp(PDU):
    GET_STATUS_QUERY_TEMPLATE = {"cmd": "get", "nr": None, "res": None}
    SET_STATUS_QUERY_TEMPLATE = {"cmd": "set", "nr": None, "res": "config"}
    HTTP_REQUEST_HEADERS = {
        "Content-type": "application/x-www-form-urlencoded",
        "Accept": "text/plain",
    }

    def __init__(self, host, timeout, login, password, http_proxy=None):
        super().__init__(host)
        self._login = login
        self._password = password
        self._timeout = float(timeout)
        self._url = f"http://{host}/output.php"
        self._http_proxy = http_proxy
        self._session = requests.Session()
        if self._http_proxy:
            self._session.proxies = {"http": self._http_proxy}

    def _authorize(self):
        login_credentials = f"user={self._login}&pwd={self._password}&end=10"
        r = self._session.post(
            f"http://{self._host}/system.php?cmd=login",
            data=login_credentials,
            headers=self.HTTP_REQUEST_HEADERS,
        )

        if r.text != "Operation Successful":
            raise BadResponse("Logging failed")

    def _logout(self):
        r = self._session.post(
            f"http://{self._host}/system.php?cmd=logout",
            headers={"Accept": "text/html"},
        )

        if r.text != "Operation Successful":
            logging.error("Logging-out failed")

    def _send_request(
        self,
        url: str,
        method: str = "POST",
        headers: dict | None = None,
        data: list | str | None = None,
        params: dict | None = None,
    ) -> Response:
        end_time = time.time() + self._timeout
        while True:
            try:
                self._authorize()
                req = requests.Request(method=method, url=url, headers=headers, data=data, params=params)
                p_req = self._session.prepare_request(req)
                response = self._session.send(p_req, timeout=self._timeout)
                if 200 <= response.status_code < 300:
                    return response
                elif time.time() > end_time:
                    raise BadResponse(
                        f"Timeout exceeded while sending request to {url}. Last status code: {response.status_code}"
                    )
            except requests.exceptions.ConnectionError as e:
                logging.error(str(e))
                if time.time() > end_time:
                    raise PduConnectionError(f"Cannot send request to following url={self._url}")
            finally:
                self._logout()

    def _get_outlet_info_values(self, port):
        payload = self.GET_STATUS_QUERY_TEMPLATE
        payload.update({"nr": str(port), "res": "values"})

        response = self._send_request(url=self._url, params=payload)
        return response.json()

    def _set_port_status(self, port, status):
        query = self.SET_STATUS_QUERY_TEMPLATE
        query["nr"] = str(port)
        post_query = self._create_query(port, status)

        self._send_request(url=self._url, params=query, data=post_query)

    def _get_outlet_config(self, port):
        payload = self.GET_STATUS_QUERY_TEMPLATE
        payload.update({"nr": str(port), "res": "config"})

        response = self._send_request(url=self._url, params=payload)
        return response.json()

    def get_port_status(self, port):
        response_dict = self._get_outlet_info_values(port=port)
        return FPFHhttp._parse_response(response_dict)

    @staticmethod
    def _parse_response(outlet_info):
        """Parse HTTP GET/POST response from PDU server."""
        try:
            if outlet_info["State"] in ["ON", "OFF"]:
                return outlet_info["State"].lower()
        except Exception:
            raise BadDeviceStatus(f"Status not found in {outlet_info} ")
        else:
            raise BadDeviceStatus(f"Status not recognized in {outlet_info['State']} ")

    @property
    def _port_setting(self):
        # Only to satisfy the contract of PDU abstraction
        return {DeviceStatus.OFF: "0", DeviceStatus.ON: "1"}

    def _create_query(self, port, status):
        post_query = self._update_payload_outlet_info(port=port)
        post_query.update({"mode": status})
        post_query_str = self._parse_post_query(post_query)
        return post_query_str

    def _update_payload_outlet_info(self, port):
        # TODO: investigate whether it's needed to supply all of the configuration just to change one parameter
        response_dict = self._get_outlet_config(port=port)
        payload_outlet_info = {
            "idis": response_dict["Settings"]["Disconnect Current [A]"],
            "outname": response_dict["Settings"]["Output Name"],
            "vrec": response_dict["Settings"]["Reconnect Voltage [V]"],
            "vdis": response_dict["Settings"]["Disconnect Voltage [V]"],
            "ddis": response_dict["Settings"]["Disconnect Delay [min]"],
            "day_on": response_dict["Timings"]["Daily"]["start"],
            "day_off": response_dict["Timings"]["Daily"]["stop"],
            "mon_active": response_dict["Timings"]["Weekly"]["Mon"]["active"],
            "mon_on": response_dict["Timings"]["Weekly"]["Mon"]["start"],
            "mon_off": response_dict["Timings"]["Weekly"]["Mon"]["stop"],
            "tue_active": response_dict["Timings"]["Weekly"]["Tue"]["active"],
            "tue_on": response_dict["Timings"]["Weekly"]["Tue"]["start"],
            "tue_off": response_dict["Timings"]["Weekly"]["Tue"]["stop"],
            "wed_active": response_dict["Timings"]["Weekly"]["Wed"]["active"],
            "wed_on": response_dict["Timings"]["Weekly"]["Wed"]["start"],
            "wed_off": response_dict["Timings"]["Weekly"]["Wed"]["stop"],
            "thu_active": response_dict["Timings"]["Weekly"]["Thu"]["active"],
            "thu_on": response_dict["Timings"]["Weekly"]["Thu"]["start"],
            "thu_off": response_dict["Timings"]["Weekly"]["Thu"]["stop"],
            "fri_active": response_dict["Timings"]["Weekly"]["Fri"]["active"],
            "fri_on": response_dict["Timings"]["Weekly"]["Fri"]["start"],
            "fri_off": response_dict["Timings"]["Weekly"]["Fri"]["stop"],
            "sat_active": response_dict["Timings"]["Weekly"]["Sat"]["active"],
            "sat_on": response_dict["Timings"]["Weekly"]["Sat"]["start"],
            "sat_off": response_dict["Timings"]["Weekly"]["Sat"]["stop"],
            "sun_active": response_dict["Timings"]["Weekly"]["Sun"]["active"],
            "sun_on": response_dict["Timings"]["Weekly"]["Sun"]["start"],
            "sun_off": response_dict["Timings"]["Weekly"]["Sun"]["stop"],
        }
        return payload_outlet_info

    def _parse_post_query(self, post_query):
        post_query_str = ""
        for key, value in post_query.items():
            post_query_str = f"{post_query_str}&{key}={value}"
        post_query_str = f"{post_query_str}&end=10"
        return post_query_str[1:]

    def reset(self, ports, time_interval=20):
        for port in ports:
            self._set_port_status(port, DeviceStatus.OFF)
            sleep(time_interval)
            self._set_port_status(port, DeviceStatus.ON)

    def get_voltage(self, port):
        response_dict = self._get_outlet_info_values(port=port)
        return float(response_dict["Output Voltage [V]"])

    def get_current(self, port):
        response_dict = self._get_outlet_info_values(port=port)
        return float(response_dict["Output Current [A]"])

    def get_energy_consumption(self, port):
        response_dict = self._get_outlet_info_values(port=port)
        return float(response_dict["Consumed Energy [kWh]"])


class FPFHsnmp(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type FPFH through SNMP.
    Class does not inherit from SnmpPdu as it can not satisfy the contract of class abstraction
    """

    AUTH_PROTOCOL = {"MD5": hmacmd5.HmacMd5.serviceID, "SHA": hmacsha.HmacSha.serviceID}
    PRIV_PROTOCOL = {"DES": des.Des.serviceID, "AES": aes.Aes.serviceID}

    def __init__(self, host, timeout, snmp_user, community="private"):
        """
        :param string host:         IP address or domain name of the FPFH device.
        :param float timeout:       Maximum number of seconds to wait for expected pdu outlet status.
        :param dict snmp_user (required only for SNMPv3): User configuration for SNMPv3 with keys: userName, authKey,
                          privKey, authProtocol (SHA/MD5), privProtocol (AES/DES)
        :param community:          Community string used by SNMPv1/2.

        :deprecated parameters:
            int fpfh_type: type of FPFH PDU  - present in original ute_pdu implementation used as penultimate value of
                                               snmp_oid, due to lack of information about its function, set to
                                               default value 1 (as proposed in original FPFH documentation)
        """
        super().__init__(host, timeout, snmp_user, community)

        self._version = 1
        self._fpfh_type = 1

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "0", DeviceStatus.ON: "1"}

    def _get_oid_value(self, status, port):
        snmp_msg = self._build_snmp_oid()
        ports_value = self._execute_get_cmd(snmp_msg)
        if status == "on":
            return rfc1902.Integer((1 << port) | int(ports_value))
        elif status == "off":
            return rfc1902.Integer((~(1 << port) & 0xFF) & int(ports_value))

    def _set_port_status(self, port, status):
        snmp_msg = self._build_snmp_oid()
        logging.info(f"SNMP: Setting port to {status}: {port}")
        self._execute_set_cmd(status, snmp_msg, port)

    def _build_snmp_oid(self):
        return f".1.3.6.1.4.1.26061.10.11.{self._fpfh_type}.0"

    def get_port_status(self, port):
        logging.info(f"SNMP: Fetching status of port: {port}")
        snmp_msg = self._build_snmp_oid()
        pdu_response = self._execute_get_cmd(snmp_msg)
        port_value = self._get_port_value(pdu_response, port)
        return self._reversed_port_settings[port_value]

    def _execute_set_cmd(self, status, snmp_msg, port):
        ports_value = self._get_oid_value(status, port)
        asyncio.run(self._execute_cmd(setCmd, ObjectType(ObjectIdentity(snmp_msg), ports_value)))

    @staticmethod
    def _get_port_value(pdu_response, port):
        return "1" if (1 << port) & int(pdu_response) else "0"
